using EplanMcp.Coverage.Tests.Mapping;
using EplanMcp.Coverage.Wrappers;

namespace EplanMcp.Coverage.Tests.Wrappers;

/// <summary>
/// The wrapper generator writes plain building blocks from catalog rows only, the same bytes every time, lists what it
/// does not wrap, rejects what it cannot copy plainly, and CI fails on a generated file that differs or is no longer
/// selected.
/// </summary>
[Trait("Size", "Medium")]
public sealed class WrapperGeneratorTests : IDisposable
{
    private const string Page = "Eplan.EplApi.Test.Page";
    private const string Dto = WrapperGenerator.ContractsFolder + "PageProperties.g.cs";
    private const string Api = WrapperGenerator.BridgeFolder + "PageApi.g.cs";
    private const string Action = WrapperGenerator.BridgeFolder + "ExportPdfParameters.g.cs";

    private readonly TempRepository _repository = FakeRepository.Create();

    public WrapperGeneratorTests() => WriteCatalog();

    [Fact]
    public void Files_WithoutASelection_AreNone()
    {
        Assert.Empty(WrapperGenerator.Files(_repository.Root));
    }

    [Fact]
    public void Files_ForAType_CopyTheSelectedPropertiesIntoADto()
    {
        Select("properties: [Name, Count, Tags, Kind]");

        string dto = WrapperGenerator.Files(_repository.Root)[Dto];
        string api = WrapperGenerator.Files(_repository.Root)[Api];

        Assert.StartsWith("// <auto-generated>\n", dto, StringComparison.Ordinal);
        Assert.Contains("#nullable enable\n\nnamespace EplanMcp.Contracts.Generated;\n", dto, StringComparison.Ordinal);
        Assert.Contains($"    /// <summary><c>P:{Page}.Name</c>.</summary>\n    public string? Name {{ get; set; }}\n", dto, StringComparison.Ordinal);
        Assert.Contains("    public int Count { get; set; }\n", dto, StringComparison.Ordinal);
        Assert.Contains("    public List<string> Tags { get; set; } = [];\n", dto, StringComparison.Ordinal);
        Assert.Contains("    public string Kind { get; set; } = string.Empty;\n", dto, StringComparison.Ordinal);
        Assert.Contains($"PageProperties Read(global::{Page} source) => new()\n", api, StringComparison.Ordinal);
        Assert.Contains("        Tags = Strings(source.Tags),\n        Kind = source.Kind.ToString(),\n", api, StringComparison.Ordinal);
        Assert.Contains("private static List<string> Strings(", api, StringComparison.Ordinal);
    }

    [Fact]
    public void Files_ForAMethodGroup_WriteTheOverloadTable_WithAReasonForEachOverloadNotWrapped()
    {
        Select("overloads: [Create]");

        Dictionary<string, string> files = new(WrapperGenerator.Files(_repository.Root));
        string api = files[Api];

        Assert.False(files.ContainsKey(Dto)); // no properties, no DTO
        Assert.Contains($"// Overload table of O:{Page}.Create: 4 overload(s) in the catalog.", api, StringComparison.Ordinal);
        Assert.Contains($"    public static void Create(global::{Page} target, string name) =>\n        target.Create(name);\n", api, StringComparison.Ordinal);
        Assert.Contains($"    public static int Create(global::{Page} target, string name, global::Eplan.EplApi.Test.Kind[] kinds) =>\n", api, StringComparison.Ordinal);
        Assert.Contains($"// M:{Page}.Create(System.String@): not wrapped, it has a by-reference", api, StringComparison.Ordinal);
        Assert.Contains($"// M:{Page}.Create(System.Object): not wrapped, the catalog excludes it (deprecated, obsolete_attribute).", api, StringComparison.Ordinal);
        Assert.Contains($"    public static string Find(object @object) =>\n        global::{Page}.Find(@object);\n", SelectAndGenerate("overloads: [Find]"), StringComparison.Ordinal);
    }

    [Fact]
    public void Files_ForAnActionRow_WriteItsParameters_AndNameTheOnesSetByHand()
    {
        _repository.Write(WrapperSelection.RelativePath, "catalog: eplan-2026.0.3\nactions:\n  - action: A:export/PDF\n    class: ExportPdfParameters\n");

        string action = WrapperGenerator.Files(_repository.Root)[Action];

        Assert.Contains("    public const string Action = \"export\";\n", action, StringComparison.Ordinal);
        Assert.Contains("    public const string Type = \"PDF\";\n", action, StringComparison.Ordinal);
        Assert.Contains("    /// <summary><c>DESTINATION</c>, required.</summary>\n    public string? DESTINATION { get; set; }\n", action, StringComparison.Ordinal);
        Assert.Contains("        Add(context, \"DESTINATION\", DESTINATION, required: true);\n        Add(context, \"LANGUAGE\", LANGUAGE, required: false);\n", action, StringComparison.Ordinal);
        Assert.Contains("// RESULT: not generated, an output parameter, read after the call; set it by hand.", action, StringComparison.Ordinal);
        Assert.Contains("// PAGE[n]: not generated, not a plain name; set it by hand.", action, StringComparison.Ordinal);
        Assert.Contains("// PASSWORD: not generated, marked sensitive in the catalog; set it by hand.", action, StringComparison.Ordinal);
    }

    [Fact]
    public void Files_AreTheSameBytesEveryTime_WithLineFeedsOnly()
    {
        Select("properties: [Name, Tags]\n    overloads: [Create]");

        SortedDictionary<string, string> first = WrapperGenerator.Files(_repository.Root);
        SortedDictionary<string, string> second = WrapperGenerator.Files(_repository.Root);

        Assert.Equal(first, second);
        Assert.All(first.Values, content => Assert.DoesNotContain('\r', content));
    }

    [Theory]
    [InlineData("properties: [Owner]")] // returns a catalog class, which has no plain DTO form
    [InlineData("properties: [Missing]")]
    [InlineData("properties: [Item]")] // indexed
    [InlineData("overloads: [Lock]")] // its only overload is by reference
    [InlineData("overloads: [Missing]")]
    public void Files_RejectASelectionTheyCannotWrapPlainly(string selection)
    {
        Select(selection);

        var error = Assert.Throws<InvalidDataException>(() => WrapperGenerator.Files(_repository.Root));

        Assert.StartsWith(WrapperSelection.RelativePath, error.Message, StringComparison.Ordinal);
    }

    [Fact]
    public void Check_AGeneratedFileThatDiffersOrIsNoLongerSelected_FailsWithTheGenerateCommand_AndGenerateFixesIt()
    {
        Select("properties: [Name]");
        CoverageCheck.Generate(_repository.Root);
        _repository.Write(Api, "// edited by hand\n");
        _repository.Write(WrapperGenerator.BridgeFolder + "OldApi.g.cs", "// once selected\n");

        List<string> problems = CoverageCheck.Problems(_repository.Root);

        Assert.Equal([Api, WrapperGenerator.BridgeFolder + "OldApi.g.cs"], problems.Select(p => p.Split(' ')[0]));
        Assert.All(problems, p => Assert.Contains(CoverageCheck.GenerateCommand, p, StringComparison.Ordinal));
        CoverageCheck.Generate(_repository.Root);
        Assert.Empty(CoverageCheck.Problems(_repository.Root));
        Assert.False(File.Exists(Path.Combine(_repository.Root, WrapperGenerator.BridgeFolder, "OldApi.g.cs")));
    }

    public void Dispose() => _repository.Dispose();

    private void Select(string entries) =>
        _repository.Write(WrapperSelection.RelativePath, $"catalog: eplan-2026.0.3\ntypes:\n  - type: T:{Page}\n    {entries}\n");

    private string SelectAndGenerate(string entries)
    {
        Select(entries);
        return WrapperGenerator.Files(_repository.Root)[Api];
    }

    private void WriteCatalog()
    {
        const string Directory = "catalog/eplan-2026.0.3/";
        string type = $"\"type\":\"T:{Page}\"";
        _repository
            .Write(Directory + "types.jsonl", $$$"""
                {"id":"T:{{{Page}}}","kind":"class","layer":"type","ns":"Eplan.EplApi.Test"}
                {"id":"T:Eplan.EplApi.Test.Kind","kind":"enum","layer":"type","ns":"Eplan.EplApi.Test","values":{"A":"0"}}

                """)
            .Write(Directory + "members/Eplan.EplApi.Test.jsonl", $$$"""
                {"id":"M:{{{Page}}}.Create(System.Object)","kind":"method","layer":"operation",{{{type}}},"group":"O:{{{Page}}}.Create","params":[{"name":"o","type":"System.Object"}],"obsolete":true,"excluded":{"reason":"deprecated","rule":"obsolete_attribute"}}
                {"id":"M:{{{Page}}}.Create(System.String)","kind":"method","layer":"operation",{{{type}}},"group":"O:{{{Page}}}.Create","params":[{"name":"name","type":"System.String"}]}
                {"id":"M:{{{Page}}}.Create(System.String,Eplan.EplApi.Test.Kind[])","kind":"method","layer":"operation",{{{type}}},"group":"O:{{{Page}}}.Create","returns":"System.Int32","params":[{"name":"name","type":"System.String"},{"name":"kinds","type":"Eplan.EplApi.Test.Kind[]"}]}
                {"id":"M:{{{Page}}}.Create(System.String@)","kind":"method","layer":"operation",{{{type}}},"group":"O:{{{Page}}}.Create","params":[{"name":"name","type":"System.String@"}]}
                {"id":"M:{{{Page}}}.Find(System.Object)","kind":"method","layer":"operation",{{{type}}},"group":"O:{{{Page}}}.Find","static":true,"returns":"System.String","params":[{"name":"object","type":"System.Object"}]}
                {"id":"M:{{{Page}}}.Lock(System.Int32@)","kind":"method","layer":"operation",{{{type}}},"group":"O:{{{Page}}}.Lock","params":[{"name":"n","type":"System.Int32@"}]}
                {"id":"P:{{{Page}}}.Count","kind":"property","layer":"operation",{{{type}}},"group":"O:{{{Page}}}.Count","returns":"System.Int32","accessors":"get"}
                {"id":"P:{{{Page}}}.Item(System.Int32)","kind":"property","layer":"operation",{{{type}}},"group":"O:{{{Page}}}.Item","returns":"System.String","params":[{"name":"i","type":"System.Int32"}],"accessors":"get"}
                {"id":"P:{{{Page}}}.Kind","kind":"property","layer":"operation",{{{type}}},"group":"O:{{{Page}}}.Kind","returns":"Eplan.EplApi.Test.Kind","accessors":"get;set"}
                {"id":"P:{{{Page}}}.Name","kind":"property","layer":"operation",{{{type}}},"group":"O:{{{Page}}}.Name","returns":"System.String","accessors":"get;set"}
                {"id":"P:{{{Page}}}.Owner","kind":"property","layer":"operation",{{{type}}},"group":"O:{{{Page}}}.Owner","returns":"Eplan.EplApi.Test.Page","accessors":"get"}
                {"id":"P:{{{Page}}}.Tags","kind":"property","layer":"operation",{{{type}}},"group":"O:{{{Page}}}.Tags","returns":"System.Collections.Specialized.StringCollection","accessors":"get"}

                """)
            .Write(Directory + "data-dictionary.jsonl", string.Empty)
            .Write(Directory + "actions.json", """
                [
                  { "id": "A:export/PDF", "action": "export", "type": "PDF", "status": "registered",
                    "parameters": [ { "name": "DESTINATION" }, { "name": "LANGUAGE", "required": false }, { "name": "RESULT", "output": true },
                                    { "name": "PAGE[n]" }, { "name": "PASSWORD", "sensitive": true } ] }
                ]
                """);
    }
}
